'use strict'
// This module processes a numerical string from standard input.
// It computes the sum of all possible arithmetic expressions
// generated by inserting either '+' operators or no operators
// between the digits of the input string.

const inputDataRows = require('fs').readFileSync(0, 'utf8').split('\n'); // Read all lines from standard input
const numericSequence = inputDataRows[0]; // The first line contains the sequence of digits
const lastCharacterIndex = numericSequence.length - 1; // Index of the last character in the sequence

// A recursive traversal function to build and evaluate expressions
const evaluatePaths = (
  currentPosition,    // The index of the character currently being considered
  accumulatedValue,   // The running total of evaluated expressions
  currentExpression   // The string representing the expression built so far
) => {
  // Base case: If we have processed up to the last character
  if (currentPosition === lastCharacterIndex) {
    // Evaluate the complete expression string and return its value
    return eval(currentExpression + numericSequence[lastCharacterIndex]);
  }

  // Recursive step: Explore two possibilities for the current character
  // 1. Append the current character followed by a '+'
  accumulatedValue += evaluatePaths(
    currentPosition + 1,
    accumulatedValue,
    currentExpression + numericSequence[currentPosition] + '+'
  )
  // 2. Append the current character without an operator (concatenation)
  + evaluatePaths(
    currentPosition + 1,
    accumulatedValue,
    currentExpression + numericSequence[currentPosition]
  );

  return accumulatedValue; // Return the sum from this branch of the recursion
};

// Initiate the expression evaluation process
// Starting from the first character (index 0), with an initial sum of 0, and an empty expression string
const overallSum = evaluatePaths(0, 0, '');

// Print the final computed sum to standard output
console.log(overallSum);